CREATE TABLE IF NOT EXISTS kemp_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), razorpay_order_id TEXT UNIQUE NOT NULL, email TEXT, main_product TEXT NOT NULL DEFAULT 'KEMP EYE Digital Experience', bump_selected BOOLEAN NOT NULL DEFAULT FALSE, amount_paise INTEGER NOT NULL CHECK (amount_paise IN (9900, 14800)), status TEXT NOT NULL DEFAULT 'created' CHECK (status IN ('created','paid','failed')), razorpay_payment_id TEXT UNIQUE, access_token_hash TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), paid_at TIMESTAMPTZ)